"""Hashing analyzer."""

from __future__ import unicode_literals

import hashlib

class CustomHasher:
  def __init__(self, algorithm='md5'):
    self.algorithm = algorithm

  def hash_data(self, data):
    hash_object = hashlib.new(self.algorithm)
    hash_object.update(data.encode('utf-8'))
    return hash_object.hexdigest()

class HashingAnalyzer:
  def __init__(self):
    self._hashers = []

  def SetHasherNames(self, hasher_name):
    self._hashers.append(hasher_name)

  def Analyze(self, data):
    results = []
    for hasher_name in self._hashers:
      hasher = CustomHasher()
      hashed_value = hasher.hash_data(data)
      attribute_name = f'{hasher_name}_hash'
      result = (hasher_name, attribute_name, hashed_value)
      results.append(result)
    return results

if __name__ == '__main__':
  analyzer = HashingAnalyzer()
  analyzer.SetHasherNames('md5')
  results = analyzer.Analyze('test data')
  print(results)
```
