Here is a C++ program that can be used to find the determinant of a matrix. The program uses recursion and the concept of cofactors to calculate the determinant.

```cpp
#include <iostream>

using namespace std;

int determinant(int mat[3][3], int n)
{
 int D = 0; // Initialize result

 if (n == 1)
 return mat[0][0];

 int temp[3][3]; // To store cofactors
 int sign = 1; // To store sign multiplier

 for (int f = 0; f < n; f++)
 {
 int m = 0, n = 0;
 for (int i = 0; i < n; i++)
 {
 for (int j = 0; j < n; j++)
 {
 if (i != 0 && j != f)
 {
 temp[m][n] = mat[i][j];
 if (n < (n - 2))
 n++;
 else
 {
 n = 0;
 m++;
 }
 }
 }
 }

 D += sign * mat[0][f] * determinant( temp, n - 1 );

 sign = -sign;
 }

 return D;
}

int main()
{
 int mat[3][3] = {{1, 9, 3},
                  {5, 6, 4},
                  {2, 8, 7}};
 int det = determinant(mat, 3);

 cout << "Determinant of the matrix is : " << det;

 return 0;
}
```

