int minAbsoluteSumDiff(List<int> nums1, List<int> nums2) {
  int n = nums1.length;
  int total = 0;
  int maxDiff = 0;
  int mod = 1000000007;
  List<int> sortedNums1 = List.from(nums1);
  sortedNums1.sort();

  for (int i = 0; i < n; i++) {
    int diff = (nums1[i] - nums2[i]).abs();
    total += diff;

    int pos = binarySearch(sortedNums1, nums2[i]);
    if (pos != n) {
      maxDiff = max(maxDiff, diff - (sortedNums1[pos] - nums2[i]).abs());
    }
    if (pos != 0) {
      maxDiff = max(maxDiff, diff - (sortedNums1[pos - 1] - nums2[i]).abs());
    }
  }

  return ((total - maxDiff) % mod + mod) % mod;
}

int binarySearch(List<int> nums, int target) {
  int left = 0, right = nums.length - 1;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (nums[mid] < target) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  return left;
}
