        PreparedStatement ps = conn.prepareStatement(myQuery);
        ps.setClob(1, myClob); // Add the CLOB into the PreparedStatement

        ResultSet rs = ps.executeQuery(); // Execute the prepared statement

        ResultSetHandler<List<MyDao>> handler = new BeanListHandler<MyDao>(MyDao.class, new BasicRowProcessor(new GenerousBeanProcessor()));
        // Define the ResultSet handler. GenerousBeanProcessor removes the requirement for column names to exactly match Java variables.

        List<MyDao> myDaoList = handler.handle(rs); // Map ResultSet to a list of MyDao objects
        return myDaoList;
    } catch (Exception e) {
        e.printStackTrace();
    }

    return null;
}
