Here is an implementation of the class Stack with the additional methods:

```cpp
#include <stack>
#include <unordered_map>

template<typename T>
class Stack {
private:
    std::stack<T> dataStack;
    std::stack<T> minStack;
    std::stack<T> maxStack;
    T sum;
    T product;
    T minimum;
    T maximum;
    T mode;
    T median;
    std::unordered_map<T, int> countMap;
    int maxCount;
    int size;
public:
    Stack() {
        sum = 0;
        product = 1;
        minimum = std::numeric_limits<T>::max();
        maximum = std::numeric_limits<T>::min();
        maxCount = 0;
        size = 0;
    }

    void push(T value) {
        dataStack.push(value);
        if (value < minimum) {
            minStack.push(value);
            minimum = value;
        } else {
            minStack.push(minimum);
        }
        if (value > maximum) {
            maxStack.push(value);
            maximum = value;
        } else {
            maxStack.push(maximum);
        }
        sum += value;
        product *= value;
        countMap[value]++;
        if (countMap[value] > maxCount) {
            maxCount = countMap[value];
            mode = value;
        }
        size++;
        updateMedian(value);
    }

    void pop() {
        if (size > 0) {
            dataStack.pop();
            minStack.pop();
            maxStack.pop();
            sum -= dataStack.top();
            product /= dataStack.top();
            countMap[dataStack.top()]--;
            if (dataStack.top() == mode) {
                maxCount--;
                if (maxCount == 0) {
                    updateMode();
                }
            }
            size--;
            updateMedian(dataStack.top());
        }
    }

    T getMinimum() {
        return minStack.top();
    }

    T getMaximum() {
        return maxStack.top();
    }

    T getAverage() {
        return sum / size;
    }

    T getMode() {
        return mode;
    }

    T getMedian() {
        return median;
    }

    T getSum() {
        return sum;
    }

    T getProduct() {
        return product;
    }

    T getRange() {
        return maximum - minimum;
    }

private:
    void updateMode() {
        for (auto& entry : countMap) {
            if (entry.second > maxCount) {
                maxCount = entry.second;
                mode = entry.first;
            }
        }
    }

    void updateMedian(T value) {
        if (size == 1) {
            median = value;
        } else if (size % 2 == 0) {
            if (value <= median) {
                median = (median * (size / 2) + value) / ((size / 2) + 1);
            } else {
                median = (median * (size / 2) + value) / (size / 2);
            }
        } else {
            if (value <= median) {
                median = (median * (size / 2) + value) / ((size / 2) + 1);
            } else {
                median = (median * (size / 2) + value) / (size / 2);
            }
        }
    }
};
```

