```python
import requests

# Authentication
response = requests.post('https://{{accountName}}.myvtex.com/api/vtexid/pub/auth/token', headers={
    'Content-Type': 'application/x-www-form-urlencoded'
}, data={
    'client_id': '{{appId}}',
    'client_secret': '{{appKey}}',
    'grant_type': 'client_credentials'
})

access_token = response.json()['access_token']

# Get orders
