# Define a DNS cache and a recursive server
class DnsCache:
    def __init__(self):
        self.cache = {}

    def get(self, domain):
        return self.cache.get(domain)

    def set(self, domain, ip_address):
        self.cache[domain] = ip_address

class RecursiveServer:
    def __init__(self, cache):
        self.cache = cache

    def resolve(self, domain):
        ip_address = self.cache.get(domain)
        if ip_address is None:
            # Simulate a DNS lookup
            ip_address = self.simulate_dns_lookup(domain)
            self.cache.set(domain, ip_address)
        return ip_address

    def simulate_dns_lookup(self, domain):
        # Simulate network latency and random DNS response
        time.sleep(random.uniform(0.1, 0.5))
        return f"{random.randint(1, 255)}.{random.randint(1, 255)}.{random.randint(1, 255)}.{random.randint(1, 255)}"

# Define the attacker class
class Attacker:
    def __init__(self, target_server, target_domain):
        self.target_server = target_server
        self.target_domain = target_domain

    def poison_cache(self, malicious_ip):
        # Inject a malicious DNS response into the cache
        self.target_server.cache.set(self.target_domain, malicious_ip)

# Define the simulation function
def simulate_attack(cache, target_domain, malicious_ip, attack_delay):
    server = RecursiveServer(cache)
    attacker = Attacker(server, target_domain)

    original_ip = server.resolve(target_domain)
    print(f"Original IP address for {target_domain}: {original_ip}")

    # Attacker waits for a certain delay before poisoning the cache
    time.sleep(attack_delay)
    attacker.poison_cache(malicious_ip)

    new_ip = server.resolve(target_domain)
    print(f"New IP address for {target_domain}: {new_ip}")

    # Check if the attack was successful
