Here's a JavaScript program that finds the greatest common divisor (GCD) of two numbers, finds the prime factors of both numbers, determines the highest power of each prime factor that divides both numbers, and handles cases where one or both of the numbers are negative.

```javascript
function gcd(num1, num2) {
  // Convert negative numbers to absolute values
  num1 = Math.abs(num1);
  num2 = Math.abs(num2);

  // Find the GCD using the Euclidean algorithm
  while (num2 !== 0) {
    var temp = num2;
    num2 = num1 % num2;
    num1 = temp;
  }

  return num1;
}

function findPrimeFactors(num) {
  var primeFactors = [];

  // Find all the factors of the number
  for (var i = 2; i <= num; i++) {
    while (num % i === 0) {
      primeFactors.push(i);
      num /= i;
    }
  }

  return primeFactors;
}

function findHighestPower(primeFactors, num) {
  var highestPowers = {};

  primeFactors.forEach(function(primeFactor) {
    var count = 0;
    while (num % primeFactor === 0) {
      count++;
      num /= primeFactor;
    }
    highestPowers[primeFactor] = count;
  });

  return highestPowers;
}

var num1 = 1024;
var num2 = 768;

var gcdResult = gcd(num1, num2);
var primeFactors1 = findPrimeFactors(num1);
var primeFactors2 = findPrimeFactors(num2);
var highestPowers1 = findHighestPower(primeFactors1, num1);
var highestPowers2 = findHighestPower(primeFactors2, num2);

console.log("GCD:", gcdResult);
console.log("Prime factors of num1:", primeFactors1);
console.log("Prime factors of num2:", primeFactors2);
console.log("Highest powers of prime factors in num1:", highestPowers1);
console.log("Highest powers of prime factors in num2:", highestPowers2);
```

