    if len(string1) != len(string2):
        return False

    mapping = {}  # Mapping from characters in string1 to characters in string2

    for i in range(len(string1)):
        char1 = string1[i]
        char2 = string2[i]

        if char1 in mapping:
            if mapping[char1] != char2:
                return False
        else:
            if char2 in mapping.values():
                return False
            mapping[char1] = char2

    return True
