void bubbleSort(int arr[], size_t n) {
 bool swapped;
 int i;
 do {
 swapped = false;
 for (i = 0; i < n - 1; ++i) {
 if (arr[i] > arr[i + 1]) {
 swap(&arr[i], &arr[i + 1]);
 swapped = true;
 }
 }
 } while (swapped);
}

int main(void)
{
