```python
import math

# Function to check if a number is prime using a probabilistic primality test
def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    k = 5
    while k * k <= n:
        if n % k == 0 or n % (k + 2) == 0:
            return False
        k += 6
    return True

# Recursive function to calculate the Fibonacci sequence up to the nth element
def fibonacci(n, reverse=False):
    if n < 0:
        return []
    if n == 0:
        return [0]
    if n == 1:
        return [0, 1]

    # Generate Fibonacci sequence
    sequence = fibonacci(n-1, reverse)
    sequence.append(sequence[-1] + sequence[-2])

    # Check primality of the new element
    if is_prime(sequence[-1]):
        if reverse:
            return sequence[::-1]
        else:
            return sequence

    # If the new element is not prime, remove it from the sequence
    sequence.pop()

    if reverse:
        return sequence[::-1]
    else:
        return sequence

# Testing the program
n = int(input("Enter the value of n: "))
reverse = input("Do you want the sequence in reverse order? (y/n): ").lower() == 'y'

sequence = fibonacci(n, reverse)
print(sequence)
```

