```java
public class MyQueue<T> implements Queue<T> {
    private List<T> queue;

    public MyQueue() {
        queue = new ArrayList<>();
    }

    @Override
    public void offer(T element) {
        queue.add(element);
    }

    @Override
    public T poll() {
        if (isEmpty()) {
            return null;
        }
        return queue.remove(0);
    }

    @Override
    public T peek() {
        if (isEmpty()) {
            return null;
        }
        return queue.get(0);
    }

    @Override
    public boolean isEmpty() {
        return queue.isEmpty();
    }

    @Override
    public int size() {
        return queue.size();
    }
}
```

