import java.util.Arrays;
import java.util.Scanner;

public class AverageGradeCalculator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter the number of students: ");
        int numStudents = scanner.nextInt();

        // Validate the input number of students
        if (numStudents <= 0) {
            System.out.println("Error: Invalid number of students!");
            return;
        }

        // Create an array to store the grades of the students
        int[] grades = new int[numStudents];

        // Prompt the user to input the grades of the students
        for (int i = 0; i < numStudents; i++) {
            System.out.println("Enter the grade for student " + (i+1) + ": ");
            int grade = scanner.nextInt();

            // Validate the input grade
            if (grade < 0 || grade > 100) {
                System.out.println("Error: Invalid grade! Grade should be between 0 and 100.");
                return;
            }

            grades[i] = grade;
        }

        // Sort the grades in ascending order
        Arrays.sort(grades);

        // Calculate the average grade
        double sum = 0;
        for (int i = 0; i < numStudents; i++) {
            sum += grades[i];
        }
        double average = sum / numStudents;

        // Display the average grade
        System.out.println("Average Grade: " + average);

        scanner.close();
    }
}

