# Import the necessary modules for finset and set operations
import finset
import set

# Define a function to convert a finset to a set
def to_set(s: finset) -> set:
    result_set = set()
    for element in s:
        result_set.add(element)
    return result_set

# Define functions to handle various operations on finsets
def union(s: finset, t: finset) -> finset:
    return s + t

def intersection(s: finset, t: finset) -> finset:
    result_set = finset()
    for element in s:
        if element in t:
            result_set.add(element)
    return result_set

def difference(s: finset, t: finset) -> finset:
    result_set = finset()
    for element in s:
        if element not in t:
            result_set.add(element)
    return result_set

# Define functions to handle bounded quantifiers
def all_elements_satisfy(s: finset, property) -> bool:
    for element in s:
        if not property(element):
            return False
    return True

def exists_element_satisfying(s: finset, property) -> bool:
    for element in s:
        if property(element):
            return True
    return False

# Define a function to determine if an element is in the set
def is_element_in_set(s: finset, element) -> bool:
    return element in s
