```c
#include <stdio.h>

/* Helper function to swap two characters a and b */
void swap(char *a, char *b) 
{ 
    char temp = *a; 
    *a = *b; 
    *b = temp; 
} 

// A utility function to find the largest among 
// two integers 
int max(int a, int b) 
{ 
    return (a > b)? a : b; 
} 

// The main function that returns the maximum number 
// possible from given array. 
// arr[]: input array 
// n: size of the array 
unsigned long long int formBiggestNo(int arr[], int n) 
{ 
    int j; 

    // Start from the right most digit and find the largest 
    // digit to include in biggest number
    unsigned long long int bigNo = 0; 
    for (int i = n-1; i >= 0 ; i--) 
    { 
        int temp = arr[i]; 
        int max = arr[i]; 
        for (j = i-1; j >= 0; j--) 
            if (arr[j] > max) 
            { 
                max = arr[j]; 
                temp = j; 
            } 

        // Swap the maximum digit with the current digit 
        // and add this digit to Big No. 
        bigNo = bigNo * 10 + max; 
        arr[temp] = arr[i]; 
        arr[i] = max; 
   } 

   return bigNo; 
} 

int main() 
{ 
    int arr[] = {22, 5, 7, 67}; 
    int n = sizeof(arr)/sizeof(arr[0]); 

    // Returns the largest number
    unsigned long long int bigNo = formBiggestNo(arr, n); 
    printf("The biggest no is %llu ", bigNo); 
    return 0; 
}
```

