#include <iostream>
using namespace std;

const int MAX_SIZE = 100; // Maximum size of the array

// Function to bubble sort an array
void bubbleSort(int arr[], int n) {
    bool swapped; // Flag to indicate if there was any swap in a pass
    for (int i = 0; i < n - 1; i++) {
        swapped = false; // Reset the flag for each pass
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j+1]) {
                swap(arr[j], arr[j+1]);
                swapped = true;
            }
        }
        if (swapped == false) // If no swap occurred in a pass, the array is already sorted
            break;
    }
}

