```javascript
import React, { useState, useEffect } from "react";
import firebase from "firebase";

const config = {
  // your Firebase project's configuration details
};

function App() {
  const [data, setData] = useState(null);

  useEffect(() => {
    // initialize Firebase app
    firebase.initializeApp(config);

    // create a reference to Firebase database
    const databaseRef = firebase.database().ref();

    // listen for real-time updates on the database reference
    databaseRef.on("value", (snapshot) => {
      // update component state with new data from Firebase
      setData(snapshot.val());
    });
  }, []);

  return (
    <div>
      {data && (
        <ul>
          {Object.keys(data).map((key) => (
            <li key={key}>{data[key]}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default App;
```

In this example, we're using the `on()` method to listen for real-time updates on the root of our Firebase database. When we receive new data from Firebase, we update the component state with it. Then, we render the data in a list using React's `useState()` hook.

